    const float* in_row = input + (long long)nc * L_in;
    float* out_row = output + (long long)nc * L_out;

    int start = out_idx * stride - padding;
    int valid_start = max(start, 0);
    int valid_end = min(start + kernel_size, L_in);
    float sum = 0.0f;
    for (int in_idx = valid_start; in_idx < valid_end; in_idx++) {
