    int C = x.size(1);
    int L_in = x.size(2);
    int L_out = (L_in + 2 * padding - kernel_size) / stride + 1;
    int NC = N * C;

    auto output = torch::empty({N, C, L_out}, x.options());

    const float* in_ptr = x.data_ptr<float>();
    float* out_ptr = output.data_ptr<float>();

    if (kernel_size == 8 && stride == 1 && padding == 4) {
